// ../es-samples/samples/es2017/async-await.js
async function demoAsyncAwait(shouldSucceed = true) {
  function fetchData() {
    return new Promise((resolve) => setTimeout(() => resolve({ data: "ES2017 payload" }), 10));
  }
  try {
    const response = await fetchData();
    return response.data;
  } catch (error) {
    return "Failed to fetch";
  }
}

// ../es-samples/samples/es2017/atomics.js
function demoAtomics() {
  const buffer = new SharedArrayBuffer(16);
  const uint8 = new Uint8Array(buffer);
  Atomics.store(uint8, 0, 42);
  return Atomics.load(uint8, 0);
}

// ../es-samples/samples/es2017/get-own-property-descriptors.js
function demoGetOwnPropertyDescriptors() {
  const source = {
    _val: 10,
    get val() {
      return this._val;
    },
    set val(v) {
      this._val = v;
    }
  };
  const descriptors = Object.getOwnPropertyDescriptors(source);
  const clone = Object.defineProperties({}, descriptors);
  clone.val = 25;
  return { sourceVal: source.val, cloneVal: clone.val, hasGetter: typeof descriptors.val.get === "function" };
}

